import AccessorArray = require( '@stdlib/array/base/accessor' );
import gfillRows = require( './index' );


// TESTS //

// The function returns a collection...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows( 'row-major', 2, 3, alpha, X, 3 ); // $ExpectType OutputArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows( 10, 2, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( true, 2, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( null, 2, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( undefined, 2, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( [], 2, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( {}, 2, 3, alpha, X, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows( 'row-major', '2', 3, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', true, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', null, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', undefined, 3, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', [], 3, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', {}, 3, alpha, X, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows( 'row-major', 2, '3', alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, true, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, null, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, undefined, alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, [], alpha, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, {}, alpha, X, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a collection...
{
	const X = new Float64Array( 6 );

	gfillRows( 'row-major', 2, 3, 10, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, true, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, null, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, undefined, X, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, {}, X, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a collection...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );

	gfillRows( 'row-major', 2, 3, alpha, 10, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, true, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, null, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, undefined, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, {}, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows( 'row-major', 2, 3, alpha, X, '3' ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, X, true ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, X, null ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, X, undefined ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, X, [] ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, X, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows(); // $ExpectError
	gfillRows( 'row-major' ); // $ExpectError
	gfillRows( 'row-major', 2 ); // $ExpectError
	gfillRows( 'row-major', 2, 3 ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, X ); // $ExpectError
	gfillRows( 'row-major', 2, 3, alpha, X, 3, 0 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a collection...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectType OutputArray<number>
	gfillRows.ndarray( 2, 3, alpha, 1, 0, new AccessorArray( X ), 3, 1, 0 ); // $ExpectType OutputArray<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows.ndarray( '2', 3, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( true, 3, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( null, 3, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( undefined, 3, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( [], 3, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( {}, 3, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows.ndarray( 2, '3', alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, true, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, null, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, undefined, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, [], alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, {}, alpha, 1, 0, X, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a collection...
{
	const X = new Float64Array( 6 );

	gfillRows.ndarray( 2, 3, 10, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, true, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, null, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, undefined, 1, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, {}, 1, 0, X, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );
	gfillRows.ndarray( 2, 3, alpha, '0', 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, true, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, null, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, undefined, 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, [], 0, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, {}, 0, X, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );
	gfillRows.ndarray( 2, 3, alpha, 1, '0', X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, true, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, null, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, undefined, X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, [], X, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, {}, X, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a sixth argument which is not a collection...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );

	gfillRows.ndarray( 2, 3, alpha, 1, 0, 10, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, true, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, null, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, undefined, 3, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, {}, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a seventh argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, '1', 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, true, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, null, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, undefined, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, [], 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, {}, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an eighth argument which is not a number...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, '0' ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, true ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, null ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, undefined ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, [] ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, {} ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const alpha = new Float64Array( [ 10.0, 20.0 ] );
	const X = new Float64Array( 6 );

	gfillRows.ndarray(); // $ExpectError
	gfillRows.ndarray( 2 ); // $ExpectError
	gfillRows.ndarray( 2, 3 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1 ); // $ExpectError
	gfillRows.ndarray( 2, 3, alpha, 1, 0, X, 3, 1, 0, 10 ); // $ExpectError
}
